class Checker:
    def islandPerimeter(self, grid, result):
        if not isinstance(result, int):
            return False

        rows = len(grid)
        if rows == 0:
            return False
        cols = len(grid[0])
        if cols == 0:
            return False

        perimeter = 0
        land_cells = 0
        for r in range(rows):
            if not isinstance(grid[r], list) or len(grid[r]) != cols:
                return False
            for c in range(cols):
                cell = grid[r][c]
                if cell not in (0, 1):
                    return False
                if cell == 1:
                    land_cells += 1
                    if r == 0 or grid[r - 1][c] == 0:
                        perimeter += 1
                    if r == rows - 1 or grid[r + 1][c] == 0:
                        perimeter += 1
                    if c == 0 or grid[r][c - 1] == 0:
                        perimeter += 1
                    if c == cols - 1 or grid[r][c + 1] == 0:
                        perimeter += 1

        return land_cells > 0 and result == perimeter
